     1	/**
     2	 * Event Service Client for Expo/React Native
     3	 * Fetches events from local API server (server-side Ticketmaster calls)
     4	 * This avoids exposing API keys in the client
     5	 */
     6	
     7	// Local API server URL - MUST use host LAN IP for physical iPhone
     8	// The server runs on the host machine and Expo Go on iPhone needs the host IP
     9	const API_BASE_URL = 'http://192.168.68.101:8080';
    10	
    11	const TIMEOUT = 15000;
    12	
    13	/**
    14	 * Fetch events from local API server
    15	 * The server handles Ticketmaster API calls with the stored API key
    16	 */
    17	async function fetchFromAPI(endpoint = '/events') {
    18	  try {
    19	    const response = await fetch(`${API_BASE_URL}${endpoint}`, {
    20	      method: 'GET',
    21	      headers: {
    22	        'Accept': 'application/json',
    23	        'Content-Type': 'application/json',
    24	      },
    25	    });
    26	    
    27	    if (!response.ok) {
    28	      console.warn(`[EventService] API error: ${response.status}`);
    29	      return null;
    30	    }
    31	    
    32	    return await response.json();
    33	  } catch (error) {
    34	    console.warn(`[EventService] Network error: ${error.message}`);
    35	    return null;
    36	  }
    37	}
    38	
    39	/**
    40	 * Fetch Ticketmaster events from local API server
    41	 */
    42	export async function fetchTicketmasterEventsViaServer() {
    43	  const data = await fetchFromAPI('/events');
    44	  
    45	  if (!data || !data.ticketmaster) {
    46	    console.warn('[EventService] No data from API server');
    47	    return [];
    48	  }
    49	  
    50	  if (data.ticketmaster.error) {
    51	    console.warn(`[EventService] Ticketmaster error: ${data.ticketmaster.error}`);
    52	    return [];
    53	  }
    54	  
    55	  return data.ticketmaster.events || [];
    56	}
    57	
    58	/**
    59	 * Fetch all events (Ticketmaster + other sources)
    60	 */
    61	export async function fetchAllEventsViaServer() {
    62	  const data = await fetchFromAPI('/events');
    63	  
    64	  if (!data) {
    65	    return { events: [], sources: [], error: 'API unavailable' };
    66	  }
    67	  
    68	  const allEvents = [];
    69	  
    70	  // Add Ticketmaster events (source is already set by API server)
    71	  if (data.ticketmaster?.events) {
    72	    allEvents.push(...data.ticketmaster.events);
    73	  }
    74	  
    75	  // Add Kulturhuset events
    76	  if (data.otherSources?.sources?.kulturhuset) {
    77	    allEvents.push(...data.otherSources.sources.kulturhuset);
    78	  }
    79	  
    80	  // Add Malmö Live events (source is normalized by API server)
    81	  if (data.otherSources?.sources?.malmolive) {
    82	    allEvents.push(...data.otherSources.sources.malmolive);
    83	  }
    84	  
    85	  // Return available sources from API server for dropdown
    86	  // The API server provides sources based on what's actually available
    87	  const sources = data.sources || [];
    88	  
    89	  return {
    90	    events: allEvents,
    91	    sources: sources,
    92	    count: allEvents.length,
    93	    ticketmasterCount: data.ticketmaster?.count || 0,
    94	  };
    95	}
    96	
    97	/**
    98	 * Fetch events from Supabase (normalized storage)
    99	 * This is the preferred endpoint when Supabase has data
   100	 */
   101	export async function fetchFromSupabase() {
   102	  const data = await fetchFromAPI('/supabase-events');
   103	  
   104	  if (!data || data.error) {
   105	    console.warn('[EventService] Supabase fetch failed, falling back to direct API');
   106	    return null;
   107	  }
   108	  
   109	  return {
   110	    events: data.events || [],
   111	    sources: data.sources || [],
   112	    count: data.count || 0,
   113	  };
   114	}
   115	
   116	/**
   117	 * Fetch events with automatic fallback
   118	 * Tries Supabase first, then falls back to direct API
   119	 */
   120	export async function fetchEventsSmart() {
   121	  // Try Supabase first (normalized data)
   122	  const supabaseData = await fetchFromSupabase();
   123	  
   124	  if (supabaseData && supabaseData.events.length > 0) {
   125	    console.log('[EventService] Using Supabase (normalized) events');
   126	    return supabaseData;
   127	  }
   128	  
   129	  // Fall back to direct API
   130	  console.log('[EventService] Falling back to direct API');
   131	  return fetchAllEventsViaServer();
   132	}
   133	
   134	/**
   135	 * Health check for API server
   136	 */
   137	export async function checkAPIHealth() {
   138	  const data = await fetchFromAPI('/health');
   139	  
   140	  if (!data) {
   141	    return { connected: false, error: 'Cannot reach API server' };
   142	  }
   143	  
   144	  return {
   145	    connected: true,
   146	    status: data.status,
   147	    ticketmasterKey: data.ticketmasterKey,
   148	  };
   149	}
   150	
   151	// Export for use in App.js
   152	export const fetchEvents = fetchAllEventsViaServer;
   153	export const fetchEventsFromSupabase = fetchEventsSmart; // Uses Supabase when available
   154	export { API_BASE_URL };
